/*
=================================================================
THEME OPTIONS - Variables in this section can be edited from the
Blogger Theme Designer (Theme > Customize).
=================================================================
*/
/*
<Group description="Theme Colors">
  <Variable name="primaryColor" description="Primary Color" type="color" default="#2563eb" value="#2563eb"/>
  <Variable name="backgroundColor" description="Background Color" type="color" default="#f3f4f6" value="#f3f4f6"/>
  <Variable name="textColor" description="Text Color" type="color" default="#111827" value="#111827"/>
</Group>
*/
