--tw-grayscale: ;--tw-hue-rotate: ;--tw-invert: ;--tw-saturate: ;--tw-sepia: ;--tw-drop-shadow: ;--tw-backdrop-blur: ;--tw-backdrop-brightness: ;--tw-backdrop-contrast: ;--tw-backdrop-grayscale: ;--tw-backdrop-hue-rotate: ;--tw-backdrop-invert: ;--tw-backdrop-opacity: ;--tw-backdrop-saturate: ;--tw-backdrop-sepia: ;--tw-contain-size: ;--tw-contain-layout: ;--tw-contain-paint: ;--tw-contain-style: }*,:before,:after{box-sizing:border-box;border-width:0;border-style:solid;border-color:#e5e7eb}:before,:after{--tw-content: ""}html,:host{line-height:1.5;-webkit-text-size-adjust:100%;-moz-tab-size:4;-o-tab-size:4;tab-size:4;font-family:ui-sans-serif,system-ui,sans-serif,"Apple Color Emoji","Segoe UI Emoji",Segoe UI Symbol,"Noto Color Emoji";font-feature-settings:normal;font-variation-settings:normal;-webkit-tap-highlight-color:transparent}body{margin:0;line-height:inherit}hr{height:0;color:inherit;border-top-width:1px}abbr:where([title]){-webkit-text-decoration:underline dotted;text-decoration:underline dotted}h1,h2,h3,h4,h5,h6{font-size:inherit;font-weight:inherit}a{color:inherit;text-decoration:inherit}b,strong{font-weight:bolder}code,kbd,samp,pre{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,Liberation Mono,Courier New,monospace;font-feature-settings:normal;font-variation-settings:normal;font-size:1em}small{font-size:80%}sub,sup{font-size:75%;line-height:0;position:relative;vertical-align:baseline}sub{bottom:-.25em}sup{top:-.5em}table{text-indent:0;border-color:inherit;border-collapse:collapse}button,input,optgroup,select,textarea{font-family:inherit;font-feature-settings:inherit;font-variation-settings:inherit;font-size:100%;font-weight:inherit;line-height:inherit;letter-spacing:inherit;color:inherit;margin:0;padding:0}button,select{text-transform:none}button,input:where([type=button]),input:where([type=reset]),input:where([type=submit]){-webkit-appearance:button;background-color:transparent;background-image:none}:-moz-focusring{outline:auto}:-moz-ui-invalid{box-shadow:none}progress{vertical-align:baseline}::-webkit-inner-spin-button,::-webkit-outer-spin-button{height:auto}[type=search]{-webkit-appearance:textfield;outline-offset:-2px}::-webkit-search-decoration{-webkit-appearance:none}::-webkit-file-upload-button{-webkit-appearance:button;font:inherit}summary{display:list-item}blockquote,dl,dd,h1,h2,h3,h4,h5,h6,hr,figure,p,pre{margin:0}fieldset{margin:0;padding:0}legend{padding:0}ol,ul,menu{list-style:none;margin:0;padding:0}dialog{padding:0}textarea{resize:vertical}input::-moz-placeholder,textarea::-moz-placeholder{opacity:1;color:#9ca3af}input::placeholder,textarea::placeholder{opacity:1;color:#9ca3af}button,[role=button]{cursor:pointer}:disabled{cursor:default}img,svg,video,canvas,audio,iframe,embed,object{display:block;vertical-align:middle}img,video{max-width:100%;height:auto}[hidden]:where(:not([hidden=until-found])){display:none}.container{width:100%}@media (min-width: 640px){.container{max-width:640px}}@media (min-width: 768px){.container{max-width:768px}}@media (min-width: 1024px){.container{max-width:1024px}}@media (min-width: 1280px){.container{max-width:1280px}}@media (min-width: 1536px){.container{max-width:1536px}}.mx-auto{margin-left:auto;margin-right:auto}.mb-2{margin-bottom:.5rem}.mb-4{margin-bottom:1rem}.mb-6{margin-bottom:1.5rem}.mb-8{margin-bottom:2rem}.mt-4{margin-top:1rem}.mt-6{margin-top:1.5rem}.mt-8{margin-top:2rem}.block{display:block}.flex{display:flex}.grid{display:grid}.hidden{display:none}.h-6{height:1.5rem}.w-6{width:1.5rem}.max-w-none{max-width:none}.list-inside{list-style-position:inside}.list-disc{list-style-type:disc}.grid-cols-1{grid-template-columns:repeat(1,minmax(0,1fr))}.items-center{align-items:center}.justify-between{justify-content:space-between}.gap-8{gap:2rem}.rounded-lg{border-radius:.5rem}.bg-gray-100{--tw-bg-opacity: 1;background-color:rgb(243 244 246 / var(--tw-bg-opacity, 1))}.bg-white{--tw-bg-opacity: 1;background-color:rgb(255 255 255 / var(--tw-bg-opacity, 1))}.p-4{padding:1rem}.p-6{padding:1.5rem}.px-3{padding-left:.75rem;padding-right:.75rem}.py-2{padding-top:.5rem;padding-bottom:.5rem}.text-center{text-align:center}.font-sans{font-family:ui-sans-serif,system-ui,sans-serif,"Apple Color Emoji","Segoe UI Emoji",Segoe UI Symbol,"Noto Color Emoji"}.text-3xl{font-size:1.875rem;line-height:2.25rem}.text-4xl{font-size:2.25rem;line-height:2.5rem}.text-sm{font-size:.875rem;line-height:1.25rem}.text-xl{font-size:1.25rem;line-height:1.75rem}.font-bold{font-weight:700}.text-blue-500{--tw-text-opacity: 1;color:rgb(59 130 246 / var(--tw-text-opacity, 1))}.text-blue-600{--tw-text-opacity: 1;color:rgb(37 99 235 / var(--tw-text-opacity, 1))}.text-gray-500{--tw-text-opacity: 1;color:rgb(107 114 128 / var(--tw-text-opacity, 1))}.text-gray-600{--tw-text-opacity: 1;color:rgb(75 85 99 / var(--tw-text-opacity, 1))}.text-gray-700{--tw-text-opacity: 1;color:rgb(55 65 81 / var(--tw-text-opacity, 1))}.text-gray-900{--tw-text-opacity: 1;color:rgb(17 24 39 / var(--tw-text-opacity, 1))}.shadow-md{--tw-shadow: 0 4px 6px -1px rgb(0 0 0 / .1), 0 2px 4px -2px rgb(0 0 0 / .1);--tw-shadow-colored: 0 4px 6px -1px var(--tw-shadow-color), 0 2px 4px -2px var(--tw-shadow-color);box-shadow:var(--tw-ring-offset-shadow, 0 0 #0000),var(--tw-ring-shadow, 0 0 #0000),var(--tw-shadow)}.hover\:text-blue-500:hover{--tw-text-opacity: 1;color:rgb(59 130 246 / var(--tw-text-opacity, 1))}.hover\:underline:hover{text-decoration-line:underline}.focus\:outline-none:focus{outline:2px solid transparent;outline-offset:2px}@media (min-width: 768px){.md\:col-span-1{grid-column:span 1 / span 1}.md\:col-span-2{grid-column:span 2 / span 2}.md\:flex{display:flex}.md\:hidden{display:none}.md\:grid-cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}}
/* Dark Mode Styles */
html.dark body { background-color: #111827; color: #d1d5db; }
html.dark .bg-white { background-color: #1f2937; }
html.dark .text-gray-500 { color: #9ca3af; }
html.dark .text-gray-600 { color: #d1d5db; }
html.dark .text-gray-700 { color: #e5e7eb; }
html.dark .text-gray-900 { color: #f9fafb; }
html.dark .text-blue-600 { color: #3b82f6; }
html.dark a { color: $(primaryColor); }

/* Layout Switcher Styles */
#posts-container.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1rem;
}
#posts-container.grid .post-snippet {
  margin-bottom: 0;
}

/* Enhanced Hover Effects */
a, button, .post-snippet {
  transition: all .2s ease-in-out;
}

.post-snippet:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / .1), 0 4px 6px -4px rgb(0 0 0 / .1);
}

#dark-mode-toggle:hover, #font-resizer button:hover, #layout-switcher button:hover {
  transform: scale(1.1);
  color: $(primaryColor) !important;
}

.footer a {
  display: inline-block; /* for transform */
}

.footer a:hover {
  transform: scale(1.2);
  color: $(primaryColor) !important;
}

/* Navigation links hover effect */
.header-nav a, .header-nav-mobile a {
  display: inline-block;
}
.header-nav a:hover, .header-nav-mobile a:hover {
  transform: scale(1.05);
}

body.script:
//
(function(){const o=document.createElement("link").relList;if(o&&o.supports&&o.supports("modulepreload"))return;for(const e of document.querySelectorAll('link[rel="modulepreload"]'))i(e);new MutationObserver(e=>{for(const t of e)if(t.type==="childList")for(const n of t.addedNodes)n.tagName==="LINK"&&n.rel==="modulepreload"&&i(n)}).observe(document,{childList:!0,subtree:!0});function s(e){const t={};return e.integrity&&(t.integrity=e.integrity),e.referrerPolicy&&(t.referrerPolicy=e.referrerPolicy),e.crossOrigin==="use-credentials"?t.credentials="include":e.crossOrigin==="anonymous"?t.credentials="omit":t.credentials="same-origin",t}function i(e){if(e.ep)return;e.ep=!0;const t=s(e);fetch(e.href,t)}})();

// Mobile Menu Logic
document.addEventListener("DOMContentLoaded",()=>{const r=document.getElementById("mobile-menu-button"),o=document.getElementById("mobile-nav");r&&o&&r.addEventListener("click",()=>{o.classList.toggle("hidden")})});

// Dark Mode Logic
const themeToggle = document.getElementById('dark-mode-toggle');
const htmlEl = document.documentElement;

// Apply the cached theme on load
const theme = localStorage.getItem('theme');
if (theme === 'dark') {
  htmlEl.classList.add('dark');
}

themeToggle.addEventListener('click', () => {
  if (htmlEl.classList.contains('dark')) {
    htmlEl.classList.remove('dark');
    localStorage.setItem('theme', 'light');
  } else {
    htmlEl.classList.add('dark');
    localStorage.setItem('theme', 'dark');
  }
});

// Font Resizer Logic
document.addEventListener('DOMContentLoaded', () => {
  const htmlEl = document.documentElement;
  const increaseButton = document.getElementById('font-increase');
  const decreaseButton = document.getElementById('font-decrease');
  const resetButton = document.getElementById('font-reset');

  if(htmlEl && increaseButton && decreaseButton && resetButton) {
    const initialFontSize = parseFloat(window.getComputedStyle(htmlEl).fontSize);

    increaseButton.addEventListener('click', () => {
      let currentSize = parseFloat(window.getComputedStyle(htmlEl).fontSize);
      htmlEl.style.fontSize = (currentSize * 1.1) + 'px';
    });

    decreaseButton.addEventListener('click', () => {
      let currentSize = parseFloat(window.getComputedStyle(htmlEl).fontSize);
      htmlEl.style.fontSize = (currentSize / 1.1) + 'px';
    });

    resetButton.addEventListener('click', () => {
      htmlEl.style.fontSize = initialFontSize + 'px';
    });
  }
});


// Lazy Load Comments Logic
const commentsContainer = document.getElementById('comments');
if (commentsContainer) {
  const observer = new IntersectionObserver((entries) => {
    if (entries[0].isIntersecting) {
      const commentsIframe = document.getElementById('comment-editor');
      const iframeSrc = commentsIframe.getAttribute('data-src');
      if (iframeSrc) {
        commentsIframe.setAttribute('src', iframeSrc);
        commentsIframe.removeAttribute('data-src');
        observer.disconnect(); // Stop observing once loaded
      }
    }
  }, { threshold: 0.1 });
  observer.observe(commentsContainer);
}

// Layout Switcher Logic
document.addEventListener('DOMContentLoaded', () => {
  const postsContainer = document.getElementById('posts-container');
  const gridViewButton = document.getElementById('grid-view');
  const listViewButton = document.getElementById('list-view');

  if (postsContainer && gridViewButton && listViewButton) {
    const layout = localStorage.getItem('layout');
    if (layout === 'grid') {
      postsContainer.classList.add('grid');
    }

    gridViewButton.addEventListener('click', () => {
      postsContainer.classList.add('grid');
      localStorage.setItem('layout', 'grid');
    });

    listViewButton.addEventListener('click', () => {
      postsContainer.classList.remove('grid');
      localStorage.setItem('layout', 'list');
    });
  }
});

//
